import { useEffect, useState } from "react";
import {
  fetchLoggedUser,
  fetchUserRepos,
  fetchCommits,
  uploadFile,
  fetchPRHeatmap,
  fetchMergeHeatmap,
} from "./api/githubApi";

import { fetchTimeline } from "./api/jiraApi"; // ⭐ IMPORTANT
import MonthYearPicker from "./components/MonthYearPicker";

function App() {
  // ---------------------- STATES ----------------------
  const [showUpload, setShowUpload] = useState(false);
  const [darkMode, setDarkMode] = useState(true);

  const [owner, setOwner] = useState("");
  const [repos, setRepos] = useState([]);
  const [selectedRepo, setSelectedRepo] = useState("");

  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [userCreatedAt, setUserCreatedAt] = useState("");

  const [commitHeatmap, setCommitHeatmap] = useState({});
  const [prHeatmap, setPrHeatmap] = useState({});
  const [mergeHeatmap, setMergeHeatmap] = useState({});
  const [commitList, setCommitList] = useState([]);

  const [selectedFile, setSelectedFile] = useState(null);
  const [uploadMessage, setUploadMessage] = useState("Uploaded via dashboard");
  const [actionType, setActionType] = useState("commits");

  // Timeline states
  const [jiraKey, setJiraKey] = useState("");
  const [timeline, setTimeline] = useState(null);
  const [loadingTimeline, setLoadingTimeline] = useState(false);

  // ---------------------- DARK MODE ----------------------
  useEffect(() => {
    document.body.style.backgroundColor = darkMode ? "#020617" : "#F1F5F9";
    document.body.style.color = darkMode ? "#E5E7EB" : "#020617";
    document.body.style.margin = "0";
  }, [darkMode]);

  // ---------------------- TOKEN ----------------------
  useEffect(() => {
    const token = new URLSearchParams(window.location.search).get("token");
    if (token) {
      localStorage.setItem("token", token);
      window.history.replaceState({}, document.title, "/");
    }
  }, []);

  // ---------------------- LOAD USER + REPOS ----------------------
  useEffect(() => {
    if (!localStorage.getItem("token")) return;

    fetchLoggedUser().then((res) => {
      setOwner(res.data.login);
      setUserCreatedAt(res.data.created_at);
    });

    fetchUserRepos().then((res) => {
      setRepos(res.data);
      if (res.data.length > 0) setSelectedRepo(res.data[0].name);
    });
  }, []);

  // ---------------------- HEATMAP: COMMITS ----------------------
  const buildCommitHeatmap = async (payload) => {
    const commitRes = await fetchCommits(payload);

    const map = {};
    const list = [];

    commitRes.data.forEach((commit) => {
      const date = commit.commit.committer.date.substring(0, 10);
      map[date] = (map[date] || 0) + 1;

      list.push({
        message: commit.commit.message,
        author: commit.commit.author.name,
        time: commit.commit.author.date,
        url: commit.html_url,
      });
    });

    setCommitHeatmap(map);
    setCommitList(list.reverse());
  };

  // ---------------------- HEATMAP: PRs ----------------------
  const buildPRHeatmap = async (payload) => {
    const res = await fetchPRHeatmap(payload);
    setPrHeatmap(res.data);
  };

  // ---------------------- HEATMAP: MERGED ----------------------
  const buildMergeHeatmap = async (payload) => {
    const res = await fetchMergeHeatmap(payload);
    setMergeHeatmap(res.data);
  };

  // ---------------------- ANALYZE ----------------------
  const fetchData = async () => {
    if (!owner || !selectedRepo) return alert("Select repo first");

    const payload = { owner, repo: selectedRepo, startDate, endDate };

    if (actionType === "commits") await buildCommitHeatmap(payload);
    if (actionType === "prs") await buildPRHeatmap(payload);
    if (actionType === "merge") await buildMergeHeatmap(payload);

    if (actionType === "clone") {
      window.open(`https://github.com/${owner}/${selectedRepo}.git`, "_blank");
    }
  };

  // ---------------------- UPLOAD ----------------------
  const handleUpload = async () => {
    if (!selectedFile) return alert("Select a file first");

    const reader = new FileReader();
    reader.onload = async () => {
      await uploadFile({
        owner,
        repo: selectedRepo,
        path: "uploads/" + selectedFile.name,
        content: reader.result.split(",")[1],
        message: uploadMessage,
      });

      alert("Uploaded!");
      setShowUpload(false);
    };

    reader.readAsDataURL(selectedFile);
  };

  // ---------------------- TIMELINE ----------------------
  const loadTimeline = async () => {
    if (!jiraKey) return alert("Enter Jira Key (e.g., SAM-23)");

    setLoadingTimeline(true);
    try {
      const res = await fetchTimeline({ key: jiraKey });
      setTimeline(res.data);
    } catch (err) {
      alert("Failed to load timeline");
    }
    setLoadingTimeline(false);
  };

  // ---------------------- RENDER HEATMAP ----------------------
  const renderHeatmap = () => {
    const map =
      actionType === "commits"
        ? commitHeatmap
        : actionType === "prs"
        ? prHeatmap
        : actionType === "merge"
        ? mergeHeatmap
        : {};

    const days = Object.keys(map).sort();

    return (
      <>
        <div className="heatmap-grid">
          {days.map((date) => {
            const level = Math.min(map[date], 4);
            return (
              <div key={date} className={`heat-box level-${level}`}>
                <span className="tooltip">
                  {date} — {map[date]}
                </span>
              </div>
            );
          })}
        </div>

        <div className="heatmap-legend">
          <span>Low</span>
          <div className="heat-box level-0" />
          <div className="heat-box level-1" />
          <div className="heat-box level-2" />
          <div className="heat-box level-3" />
          <div className="heat-box level-4" />
          <span>High</span>
        </div>
      </>
    );
  };

  // ---------------------- UI ----------------------
  return (
    <div style={styles.container}>
      {/* TOP BAR */}
      <div style={styles.topBar}>
        <h2>🚀 GitHub Analytics</h2>

        <div style={{ display: "flex", gap: 10 }}>
          <button onClick={() => setDarkMode(!darkMode)}>
            {darkMode ? "☀ Light" : "🌙 Dark"}
          </button>

          <button
            onClick={() =>
              window.open(`https://github.com/${owner}/${selectedRepo}.git`)
            }
          >
            ⬇ Clone Repo
          </button>

          <button onClick={() => setShowUpload(!showUpload)}>⬆ Upload</button>
        </div>
      </div>

      {/* LOGIN */}
      {!owner && (
        <button
          onClick={() =>
            (window.location.href = "http://localhost:8080/auth/github")
          }
        >
          Login with GitHub
        </button>
      )}

      {/* MAIN UI */}
      {owner && (
        <>
          {/* Upload Box */}
          {showUpload && (
            <div style={styles.uploadBox}>
              <input
                type="file"
                onChange={(e) => setSelectedFile(e.target.files[0])}
              />
              <input
                type="text"
                placeholder="Commit message"
                value={uploadMessage}
                onChange={(e) => setUploadMessage(e.target.value)}
              />
              <button onClick={handleUpload}>Upload</button>
            </div>
          )}

          {/* Controls */}
          <div style={styles.form}>
            <select onChange={(e) => setSelectedRepo(e.target.value)}>
              {repos.map((r) => (
                <option key={r.id} value={r.name}>
                  {r.name}
                </option>
              ))}
            </select>

            <MonthYearPicker
              userCreatedAt={userCreatedAt}
              onChange={({ startDate, endDate }) => {
                setStartDate(startDate);
                setEndDate(endDate);
              }}
            />

            <select onChange={(e) => setActionType(e.target.value)}>
              <option value="commits">Commits</option>
              <option value="prs">Pull Requests</option>
              <option value="merge">Merged PRs</option>
              <option value="clone">Clone Repo</option>
            </select>

            <button onClick={fetchData}>Analyze</button>
          </div>

          {/* Heatmap */}
          <div style={styles.heatmapBox}>
            <h3>Activity Heatmap</h3>
            {renderHeatmap()}
          </div>

          {/* Commit List */}
          {commitList.length > 0 && (
            <div style={styles.timelineBox}>
              <h3>🟢 Recent Commits</h3>

              {commitList.slice(0, 10).map((c, idx) => (
                <div key={idx} style={styles.commitItem}>
                  <b>{c.message}</b>
                  <p>
                    {c.author} • {new Date(c.time).toLocaleString()}
                  </p>
                  <a href={c.url} target="_blank">
                    View →
                  </a>
                </div>
              ))}
            </div>
          )}

          {/* Jira Timeline */}
          <div style={styles.timelineForm}>
            <input
              type="text"
              placeholder="Enter Jira Key (SAM-23)"
              value={jiraKey}
              onChange={(e) => setJiraKey(e.target.value)}
            />
            <button onClick={loadTimeline}>
              {loadingTimeline ? "Loading..." : "Load Timeline"}
            </button>
          </div>

          {timeline && (
            <div style={styles.timelineBox}>
              <h3>📌 Jira + GitHub Timeline</h3>

              <p>
                <b>Issue:</b> {timeline.issue.key} —{" "}
                {timeline.issue.summary}
              </p>

              <p>
                <b>PR:</b> #{timeline.pr.number} — {timeline.pr.title} (
                <a href={timeline.pr.html_url} target="_blank">
                  Open PR
                </a>
                )
              </p>

              <h4>⏳ Timeline Events</h4>

              {timeline.timeline.map((ev, idx) => (
                <div key={idx} style={styles.timelineEvent}>
                  <b>{ev.type}</b> — {ev.timestamp}
                  <br />
                  👤 {ev.actor}
                  <br />
                  📝 {ev.message}
                  {ev.time_to_next_review_readable && (
                    <p>⏭ Next Review: {ev.time_to_next_review_readable}</p>
                  )}
                  {ev.time_to_next_commit_readable && (
                    <p>⏭ Next Commit: {ev.time_to_next_commit_readable}</p>
                  )}
                </div>
              ))}

              <h4>🔁 Rework Cycles: {timeline.reworkCycles}</h4>
            </div>
          )}
        </>
      )}

      {/* CSS */}
      <style>{`
        .heatmap-grid {
          display: grid;
          grid-template-columns: repeat(53, 12px);
          gap: 5px;
          justify-content: center;
        }
        .heat-box {
          width: 12px;
          height: 12px;
          border-radius: 3px;
          position: relative;
          cursor: pointer;
        }
        .heat-box:hover {
          transform: scale(1.5);
          z-index: 2;
        }
        .tooltip {
          opacity: 0;
          position: absolute;
          background: black;
          color: white;
          padding: 3px 6px;
          border-radius: 4px;
          font-size: 10px;
          bottom: 18px;
          left: 50%;
          transform: translateX(-50%);
          transition: opacity 0.2s;
        }
        .heat-box:hover .tooltip {
          opacity: 1;
        }
        .level-0 { background: #e5e7eb; }
        .level-1 { background: #bbf7d0; }
        .level-2 { background: #4ade80; }
        .level-3 { background: #16a34a; }
        .level-4 { background: #166534; }
        .heatmap-legend {
          margin-top: 10px;
          display: flex;
          gap: 6px;
          align-items: center;
          justify-content: center;
        }
      `}</style>
    </div>
  );
}

